(() => { const out = {cards: [], links: [], labels: []};
 document.querySelectorAll('[data-card-id]').forEach(el => { if (!el.matches('article')) return; const r = el.getBoundingClientRect();
   out.cards.push({id: el.dataset.cardId, color: el.dataset.color, x: r.x, y: r.y, w: r.width, h: r.height, title: (el.querySelector('.card-title, h3, h2') || el).innerText.split('\n')[0]}); });
 document.querySelectorAll('g.link').forEach(g => { const p = g.querySelector('.link-line'), a = g.querySelector('.link-arrow'), m = p.getScreenCTM();
   out.links.push({id: g.dataset.linkId, kind: g.classList.contains('link-wiki') ? 'wiki' : 'direct', from: g.dataset.from, to: g.dataset.to,
     d: p.getAttribute('d'), arrow: a ? a.getAttribute('d') : '', m: [m.a, m.b, m.c, m.d, m.e, m.f], len: p.getTotalLength()}); });
 document.querySelectorAll('.link-label').forEach(el => { const r = el.getBoundingClientRect(); out.labels.push({id: el.dataset.linkId, text: el.innerText, x: r.x, y: r.y, w: r.width, h: r.height}); });
 let pre = document.getElementById('__dump'); if (!pre) { pre = document.createElement('pre'); pre.id = '__dump'; pre.style.cssText = 'position:fixed;left:0;top:0;width:1px;height:1px;overflow:hidden;opacity:0;white-space:pre;'; document.body.appendChild(pre); }
 pre.textContent = JSON.stringify(out); })()

